  import {
    collapseAnnotationValue,
    TAG_NOT_FOUND_INDEX,
    getFixedStoryPath,
    buildStoryErrorMessage,
    buildReqErrorMessage,
  } from "./helpers/valid-annotation-utils";
  ...
  function createStoryFix(context: any, comment: any, fixed: string): null | (() => any) {
    const sourceCode = context.getSourceCode();
    const commentText = sourceCode.getText(comment);
    const search = "@story";
    const tagIndex = commentText.indexOf(search);
    // @story docs/stories/008.0-DEV-AUTO-FIX.story.md
    // @req REQ-AUTOFIX-SAFE - Skip auto-fix when @story tag cannot be reliably located
    if (tagIndex === TAG_NOT_FOUND_INDEX) {
      return null;
    }
    ...
    const valueMatch = rest.match(/[^\S\r\n]*([^\r\n*]+)/);
    // @req REQ-AUTOFIX-SAFE - Abort auto-fix when story value range cannot be safely determined
    if (!valueMatch || valueMatch.index === undefined) {
      return null;
    }
    ...
    const fixRange: [number, number] = [ start + valueStartInComment, start + valueEndInComment ];
    return () => (fixer: any) => fixer.replaceTextRange(fixRange, fixed);
  }

  function reportInvalidStoryFormatWithFix(context: any, comment: any, collapsed: string, fixed: string): void {
    const fixFactory = createStoryFix(context, comment, fixed);
    // @req REQ-AUTOFIX-SAFE - Fall back to reporting without fix when safe fix cannot be created
    if (!fixFactory) {
      reportInvalidStoryFormat(context, comment, collapsed, getResolvedDefaults());
      return;
    }

    context.report({
      node: comment as any,
      messageId: "invalidStoryFormat",
      data: { details: buildStoryErrorMessage("invalid", collapsed, getResolvedDefaults()) },
      fix: fixFactory(),
    });
  }

  function validateStoryAnnotation(context: any, comment: any, rawValue: string, options: ResolvedAnnotationOptions): void {
    const trimmed = rawValue.trim();
    if (!trimmed) {
      context.report({ messageId: "invalidStoryFormat", data: { details: buildStoryErrorMessage("missing", null, options) } });
      return;
    }
    const collapsed = collapseAnnotationValue(trimmed);
    const pathPattern = options.storyPattern;
    if (pathPattern.test(collapsed)) { return; }
    if (/\s/.test(trimmed)) {
      reportInvalidStoryFormat(context, comment, collapsed, options);
      return;
    }
    const fixed = getFixedStoryPath(collapsed);
    // @req REQ-AUTOFIX-FORMAT - Apply suffix-only auto-fix when it yields a pattern-compliant path
    if (fixed && pathPattern.test(fixed)) {
      reportInvalidStoryFormatWithFix(context, comment, collapsed, fixed);
      return;
    }
    reportInvalidStoryFormat(context, comment, collapsed, options);
  }

  export default {
    meta: {
      ...
      /**
       * This rule's fixable support is limited to safe @story path suffix normalization per Story 008.0.
       * Fixes are limited strictly to adjusting the suffix portion of the @story path ...
       * @story docs/stories/008.0-DEV-AUTO-FIX.story.md
       * @req REQ-AUTOFIX-SAFE
       * @req REQ-AUTOFIX-PRESERVE
       */
      fixable: "code",
    },
    create(context) { ... }
  };

  src/rules/helpers/valid-annotation-utils.ts
  -------------------------------------------
  export function getFixedStoryPath(original: string): string | null {
    if (original.includes("..")) {
      // @req REQ-AUTOFIX-SAFE - reject potentially unsafe traversal
      return null;
    }

    if (/\.story\.md$/.test(original)) {
      // already correct; no fix applied
      return null;
    }

    if (/\.story$/.test(original)) {
      // @req REQ-AUTOFIX-FORMAT / REQ-AUTOFIX-PRESERVE
      return `${original}.md`;
    }

    if (/\.md$/.test(original)) {
      return original.replace(/\.md$/, ".story.md");
    }

    return `${original}.story.md`;
  }

  These helpers ensure only suffix-based, non-destructive changes are made, aborting fixes when ambiguous or unsafe.,Documentation of auto-fix capabilities for this story in user-facing docs:

  user-docs/api-reference.md
  --------------------------
  ### traceability/require-story-annotation

  "... When you adopt multi-story `@implements` annotations, this rule also accepts `@implements` as an alternative way to prove story coverage ... When run with `--fix`, the rule inserts a single-line placeholder JSDoc `@story` annotation above missing functions, methods, TypeScript declare functions, and interface method signatures using a built-in template aligned with Story 008.0. This template is currently fixed but structured for future configurability, and fixes are strictly limited to adding this placeholder annotation without altering the function body or changing any runtime behavior. Selective enabling of different auto-fix behaviors ... is planned for a future version."

  ### traceability/valid-annotation-format

  "Description: ... When run with `--fix`, the rule limits changes to safe `@story` path suffix normalization only—for example, adding `.md` when the path ends with `.story`, or adding `.story.md` when the base path has no extension—using targeted replacements implemented in the `getFixedStoryPath` and `reportInvalidStoryFormatWithFix` helpers. It does not change directories, infer new story names, or modify any surrounding comment text or whitespace, in line with Story 008.0; more advanced path normalization strategies and selective toggles ... are not yet implemented."

